-- V105 explicit data classification/handling policy. Unclassified fields fail closed in the runtime policy boundary.
CREATE TABLE IF NOT EXISTS data_classification_policies(tenant_id text NOT NULL,id text NOT NULL,policy_key text NOT NULL,version integer NOT NULL CHECK(version>=1),status text NOT NULL CHECK(status IN ('DRAFT','PUBLISHED','RETIRED')),definition_hash char(64) NOT NULL CHECK(definition_hash ~ '^[a-f0-9]{64}$'),rules_json jsonb NOT NULL,created_by_hash char(64) NOT NULL,created_at timestamptz NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,policy_key,version));ALTER TABLE data_classification_policies ENABLE ROW LEVEL SECURITY;ALTER TABLE data_classification_policies FORCE ROW LEVEL SECURITY;CREATE POLICY data_classification_policy_tenant ON data_classification_policies USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE UNIQUE INDEX IF NOT EXISTS one_published_data_policy ON data_classification_policies(tenant_id,policy_key) WHERE status='PUBLISHED';
